import {copyHTML,copyRaw} from './site-copy.js';
import {brandName,brandHTML} from './brand-state.js';
import {backend} from './backend.js';
import {escape as e} from './store.js';
let content={mission:'',founders:[],contributors:[],support:{email:'',phone:''}},error='',draft=[];
export function safePortrait(value){try{const url=new URL(value);return url.protocol==='https:'?url.href:'';}catch{return '';}}
export const photoPosition=value=>Number.isFinite(Number(value))?Math.max(0,Math.min(100,Number(value))):50;
export function normalizeAbout(value={}){return {support:{email:String(value.support?.email||'').slice(0,254),phone:String(value.support?.phone||'').slice(0,30)},mission:String(value.mission||'').slice(0,12000),founders:Array.isArray(value.founders)?value.founders.slice(0,20).filter(x=>x&&typeof x.name==='string').map(x=>({name:x.name.slice(0,120),bio:String(x.bio||'').slice(0,4000),photo:safePortrait(x.photo),x:photoPosition(x.x??50),y:photoPosition(x.y??50),fit:x.fit==='contain'?'contain':'cover'})):[],contributors:Array.isArray(value.contributors)?value.contributors.filter(x=>typeof x==='string').slice(0,200).map(x=>x.slice(0,300)):[]};}
export async function loadAbout(){try{const rows=await backend.read('lexamah_about');content=normalizeAbout(rows?.[0]?.content);error='';}catch{error='Run supabase/about.sql in SQL Editor to enable editing this page.';}return content;}
export function aboutPage(){return `<div class="heading"><div><span class="eyebrow">${copyHTML("about.4595424e2e25")}</span><h1>${copyHTML("about.4efca0d10c5f")} ${brandHTML()}</h1><p>${copyHTML("about.9a32fd474876")}</p></div></div><section class="card mission-card"><span class="eyebrow">${copyHTML("about.0576ef3816e4")} ${brandHTML(true)}</span><h2>${copyHTML("about.15071e06f817")}</h2><p class="mission-copy">${e(content.mission||'Our mission will be shared here soon.')}</p></section><div class="section-title"><h2>${copyHTML("about.7784e64e2feb")}</h2></div><div class="grid">${content.founders.length?content.founders.map(founder=>`<article class="card founder-card">${founder.photo?`<img src="${e(founder.photo)}" alt="${e(founder.name)}" style="object-fit:${founder.fit};object-position:${founder.x}% ${founder.y}%" loading="lazy" referrerpolicy="no-referrer">`:`<div class="founder-initial">${e(founder.name.charAt(0))}</div>`}<h3>${e(founder.name)}</h3><p>${e(founder.bio)}</p></article>`).join(''):`<p class="muted">${copyHTML("about.5d3caf432777")}</p>`}</div><section class="card" style="margin-top:28px"><div class="card-head"><h2>${copyHTML("about.889a764977a0")}</h2></div>${content.contributors.length?`<ul class="contributors-list">${content.contributors.map(name=>`<li>${e(name)}</li>`).join('')}</ul>`:`<p class="muted">${copyHTML("about.fc8a29e9bfc3")} ${brandHTML()}.</p>`}</section>${supportSection()}`;}
function founderFields(){return draft.map((founder,i)=>`<section class="card" style="margin:15px 0"><div class="card-head"><h3>${copyHTML("about.23ae45f425f7")} ${i+1}</h3><button class="btn danger" type="button" data-remove-founder="${i}">${copyHTML("about.f52431ba6522")}</button></div><label for="founder-name-${i}">${copyHTML("about.f13a64ba2fea")}</label><input id="founder-name-${i}" name="founder-name-${i}" required maxlength="120" value="${e(founder.name)}"><label for="founder-bio-${i}">${copyHTML("about.3933b1802161")}</label><textarea id="founder-bio-${i}" name="founder-bio-${i}" maxlength="4000">${e(founder.bio)}</textarea><label for="founder-photo-${i}">${copyHTML("about.329b80e7afa4")}</label><input id="founder-photo-${i}" name="founder-photo-${i}" type="url" value="${e(founder.photo)}" placeholder="${copyHTML("about.ab04e20ed4f2")}"><label for="founder-file-${i}">${copyHTML("about.f9718e67aa23")}</label><input id="founder-file-${i}" name="founder-file-${i}" type="file" accept=".jpg,.jpeg,.png,.webp"><p class="muted">${copyHTML("about.d0b3c58fc2f1")}</p><img id="founder-preview-${i}" class="portrait-preview ${founder.photo?'':'hidden'}" ${founder.photo?`src="${e(founder.photo)}"`:''} alt="Picture preview" style="object-fit:${founder.fit||'cover'};object-position:${founder.x??50}% ${founder.y??50}%"><label for="founder-fit-${i}">${copyHTML("about.223e3547d48e")}</label><select id="founder-fit-${i}"><option value="cover" ${founder.fit!=='contain'?'selected':''}>${copyHTML("about.c8d2a7d42535")}</option><option value="contain" ${founder.fit==='contain'?'selected':''}>${copyHTML("about.dca9cae809dd")}</option></select><label for="founder-x-${i}">${copyHTML("about.a004fe1365ec")}</label><input id="founder-x-${i}" type="range" min="0" max="100" value="${founder.x??50}"><label for="founder-y-${i}">${copyHTML("about.40a3878f39f3")}</label><input id="founder-y-${i}" type="range" min="0" max="100" value="${founder.y??50}"></section>`).join('');}
export function aboutEditor(){draft=structuredClone(content.founders);return `<section class="card"><div class="card-head"><h2>${copyHTML("about.4efca0d10c5f")} ${brandHTML()}</h2><span class="pill">${copyHTML("about.b191fca34a80")}</span></div>${error?`<div class="notice">${e(error)}</div>`:`<form id="about-form"><label for="about-mission">${copyHTML("about.00fdceacb47e")}</label><textarea id="about-mission" name="mission" rows="6" maxlength="12000">${e(content.mission)}</textarea><div class="section-title"><h2>${copyHTML("about.75f977702daa")}</h2><button class="btn" type="button" id="add-founder">${copyHTML("about.200e3873b755")}</button></div><div id="founder-fields">${founderFields()}</div><label for="about-contributors">${copyHTML("about.f4faab6fba74")}</label><textarea id="about-contributors" name="contributors" rows="6">${e(content.contributors.join('\n'))}</textarea><label for="support-email">${copyHTML("about.0514ddd75855")}</label><input id="support-email" type="email" maxlength="254" value="${e(content.support.email)}" placeholder="${copyHTML("about.25d4b1bcb69c")}"><label for="support-phone">${copyHTML("about.2ec6d8c080de")}</label><input id="support-phone" type="tel" maxlength="30" value="${e(content.support.phone)}" placeholder="+234…"><p id="about-status" class="muted" role="status"></p><div class="actions"><button class="btn primary" id="about-save">${copyHTML("about.defa65f6991a")}</button><button class="btn" type="button" data-route="about">${copyHTML("about.1509c71df048")}</button></div></form>`}</section>`;}
export function bindAboutEditor(ui){const form=document.querySelector('#about-form');if(!form)return;const capture=()=>{draft=draft.map((x,i)=>({name:document.querySelector(`#founder-name-${i}`).value,bio:document.querySelector(`#founder-bio-${i}`).value,photo:document.querySelector(`#founder-photo-${i}`).value,file:document.querySelector(`#founder-file-${i}`).files?.[0]||x.file,x:Number(document.querySelector(`#founder-x-${i}`).value),y:Number(document.querySelector(`#founder-y-${i}`).value),fit:document.querySelector(`#founder-fit-${i}`).value}));};const bindRows=()=>{draft.forEach((founder,i)=>{const preview=document.querySelector(`#founder-preview-${i}`);const adjust=()=>{preview.style.objectFit=document.querySelector(`#founder-fit-${i}`).value;preview.style.objectPosition=`${document.querySelector(`#founder-x-${i}`).value}% ${document.querySelector(`#founder-y-${i}`).value}%`;};['fit','x','y'].forEach(key=>document.querySelector(`#founder-${key}-${i}`).oninput=adjust);const file=document.querySelector(`#founder-file-${i}`);file.onchange=()=>{if(file.files[0]){if(preview.dataset.blob)URL.revokeObjectURL(preview.dataset.blob);const blob=URL.createObjectURL(file.files[0]);preview.dataset.blob=blob;preview.src=blob;preview.classList.remove('hidden');adjust();}};document.querySelector(`#founder-photo-${i}`).oninput=event=>{const url=safePortrait(event.target.value);if(url){preview.src=url;preview.classList.remove('hidden');adjust();}};if(founder.file){const blob=URL.createObjectURL(founder.file);preview.dataset.blob=blob;preview.src=blob;preview.classList.remove('hidden');}});document.querySelectorAll('[data-remove-founder]').forEach(button=>button.onclick=()=>{capture();draft.splice(Number(button.dataset.removeFounder),1);document.querySelector('#founder-fields').innerHTML=founderFields();bindRows();});};bindRows();document.querySelector('#add-founder').onclick=()=>{if(draft.length>=20){ui.toast(copyRaw("about.49b9f2ae6b7e"));return;}capture();draft.push({name:'',bio:'',photo:'',x:50,y:50,fit:'cover'});document.querySelector('#founder-fields').innerHTML=founderFields();bindRows();};form.onsubmit=async event=>{event.preventDefault();const submit=document.querySelector('#about-save'),status=document.querySelector('#about-status');submit.disabled=true;try{capture();const founders=[];for(let i=0;i<draft.length;i++){const founder={...draft[i],name:draft[i].name.trim()};if(!founder.name)throw new Error(copyRaw("about.bc7b37aa96c7"));const file=document.querySelector(`#founder-file-${i}`).files[0]||founder.file;if(file){status.textContent=`Uploading picture ${i+1}…`;founder.photo=await backend.uploadPortrait(file);}else if(founder.photo&&!safePortrait(founder.photo))throw new Error(copyRaw("about.d0bc466a6946"));founders.push(founder);}const contributors=document.querySelector('#about-contributors').value.split('\n').map(x=>x.trim()).filter(Boolean);if(contributors.length>200||contributors.some(x=>x.length>300))throw new Error(copyRaw("about.4acfb268d0b8"));const email=document.querySelector('#support-email').value.trim(),phone=document.querySelector('#support-phone').value.trim();if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error(copyRaw("about.3b9e9464da58"));if(phone&&!/^\+?[0-9 ()-]{5,30}$/.test(phone))throw new Error(copyRaw("about.9f16fc46118c"));const next=normalizeAbout({support:{email,phone},mission:document.querySelector('#about-mission').value,founders,contributors});status.textContent=copyRaw("about.582e0f1abad4");await backend.saveAbout(next);content=next;await ui.reload();ui.render();ui.toast(`${copyRaw("about.c381a5010d7e")}${brandName()}${copyRaw("about.d7d6f303f966")}`);}catch(err){status.textContent=err.message;}finally{submit.disabled=false;}};}

export function supportSection(){const {email,phone}=content.support;const validEmail=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);const validPhone=/^\+?[0-9 ()-]{5,30}$/.test(phone);return `<section class="card" style="margin-top:24px"><h2>${copyHTML("about.aea69e9d7676")}</h2><p class="muted">${copyHTML("about.d868ce4195e5")} ${brandHTML()} ${copyHTML("about.ed06163bf0e0")}</p><div class="actions">${validEmail?`<a class="btn primary" href="mailto:${e(email)}">${e(email)}</a>`:''}${validPhone?`<a class="btn" href="tel:${phone.replace(/[^0-9+]/g,'')}">${e(phone)}</a>`:''}${!validEmail&&!validPhone?`<p class="muted">${copyHTML("about.63be8c4c38ee")}</p>`:''}</div></section>`;}
export function supportPage(){return `<div class="heading"><div><span class="eyebrow">${copyHTML("about.22ab405e1c7d")}</span><h1>${copyHTML("about.aea69e9d7676")}</h1></div></div>${supportSection()}`;}
